import 'package:dsbridge_flutter/dsbridge_flutter.dart';

class JsApi extends JavaScriptNamespaceInterface {
  @override
  void register() {
    registerFunction(testSyn);
    registerFunction(testAsyn);
  }
  String testSyn(dynamic msg) => "$msg［syn call］";
  void testAsyn(dynamic msg, CompletionHandler handler) => handler.complete("$msg [ asyn call]");
}

void main() async {
  final controller = DWebViewController();
  controller.addJavaScriptObject(JsApi());
  // load your page, then you can call JS functions:
  controller.callHandler('addValue', args: [3,4], handler: (ret) => print(ret));
}
